vendor_detections.query:
// Wiz Threat Center / Registry events query (Resource Graph style)
let ciIdentities = dynamic([
  "arn:aws:iam::000000000000:role/github-actions-ecr-push",
  "projects/example/serviceAccounts/cloudbuild-push@example.iam.gserviceaccount.com"
]);
let protectedRepoPrefix = "prod/";
RegistryEvent
| where action == "PutManifest"
  and repository startswith protectedRepoPrefix
  and tag != ""
| where principal !in (ciIdentities)
| project eventTime, registry, repository, tag, digest, principal, sourceIP, userAgent
